test("Studio quotas replace the default in both directions and fall back for unlisted tenants", () => {
  const dispatch = planner(catalog());
  assert.deepEqual(dispatch(book("large", "orchid", 8)), {status: "booked", id: "large", remaining: 0});
  assert.deepEqual(dispatch(book("overflow")), {status: "full", id: "overflow", remaining: 0});
  assert.deepEqual(dispatch(book("small-over", "small", 3)), {status: "full", id: "small-over", remaining: 2});
