  assert.deepEqual(dispatch(book("fallback-over", "other", 6)), {status: "full", id: "fallback-over", remaining: 5});
  assert.deepEqual(dispatch(book("fallback-fit", "other", 5)), {status: "booked", id: "fallback-fit", remaining: 0});
