  const dispatch = planner(catalog());
  dispatch(book("source", "orchid", 7));
  dispatch(book("destination", "orchid", 2, "2025-05-02"));
  assert.deepEqual(dispatch(renewal("source", "renewed")), {status: "full", id: "renewed", remaining: 6});
  dispatch({action: "cancel", service: "studio", id: "destination"});
  assert.deepEqual(dispatch(renewal("source", "renewed")), {status: "booked", id: "renewed", remaining: 1});
  assert.deepEqual(dispatch(renewal("source", "renewed")), {status: "replay", id: "renewed"});
