  assert.deepEqual(dispatch(book("extra", "orchid", 2, "2025-05-02")), {status: "full", id: "extra", remaining: 1});
  assert.equal(dispatch(renewal("source", "later", {day: "2025-06-02", units: 8})).status, "booked");
  dispatch({action: "cancel", service: "studio", id: "source"});
  assert.deepEqual(dispatch(renewal("source", "missing")), {status: "missing", id: "source"});
  assert.deepEqual(dispatch(renewal("unknown", "missing")), {status: "missing", id: "unknown"});
